const auto result = AdvancingFront::makeGeometryBasedMesh();
std::printf("{\"geometry_result\":{\"status\":%d,\"done\":%d,\"ids\":[%ld,%ld,%ld],\"vertices\":[",
            static_cast<int>(result), result == ADVF_GEOMETRY_MESH_DONE,
            lastVertexId, lastEdgeId, lastFaceId);
bool first = true;
for (auto* vertex : vertices) {
  std::printf("%s[%ld,%.17g,%.17g]", first ? "" : ",", vertex->getId(), vertex->getX(), vertex->getY());
  first = false;
}
std::printf("],\"edges\":[");
first = true;
for (auto* edge : edges) {
  std::printf("%s[%ld,%ld,%ld,%d]", first ? "" : ",", edge->getId(), edge->getV1()->getId(), edge->getV2()->getId(), edge->isFree());
  first = false;
}
std::printf("],\"faces\":[");
first = true;
for (auto* face : mesh) {
  std::printf("%s[%ld,%ld,%ld,%ld,%.17g]", first ? "" : ",", face->getId(), face->getV1()->getId(), face->getV2()->getId(), face->getV3()->getId(), face->orientedSurface());
  first = false;
}
std::printf("],\"front\":[");
first = true;
for (auto* edge : front) {
  std::printf("%s%ld", first ? "" : ",", edge->getId());
  first = false;
}
std::printf("],\"rejected\":[");
first = true;
for (auto* edge : rejected) {
  std::printf("%s%ld", first ? "" : ",", edge->getId());
  first = false;
}
std::printf("],\"inner\":[%zu,%zu,%zu],\"tree_owners\":[%zu,%zu,%zu]}}\n",
            innerVertices.size(), innerEdges.size(), mesh.size(), quadtree->getVertices().size(),
            quadtree->getEdges().size(), quadtree->getMesh().size());
throw PrefixReached{};

std::printf("{\"geometry_event\":\"retirement_queued\",\"pass\":%d,\"edge\":%ld,\"queues\":[%zu,%zu],\"views\":[%zu,%zu,%zu]}\n", frontBased, e->getId(), front.size(), rejected.size(), vertices.size(), innerVertices.size(), frontVertices.size());
vertices.remove(best);
innerVertices.remove(best);
frontVertices.remove(best);


std::printf("{\"geometry_event\":\"retirement_detached\",\"pass\":%d,\"edge\":%ld,\"queues\":[%zu,%zu],\"views\":[%zu,%zu,%zu]}\n", frontBased, e->getId(), front.size(), rejected.size(), vertices.size(), innerVertices.size(), frontVertices.size());
delete best;
std::printf("{\"geometry_event\":\"retirement_deleted\",\"pass\":%d,\"edge\":%ld,\"queues\":[%zu,%zu],\"views\":[%zu,%zu,%zu]}\n", frontBased, e->getId(), front.size(), rejected.size(), vertices.size(), innerVertices.size(), frontVertices.size());
